25	   private WeightedList(final List<? extends Weighted<E>> items) {
26	      this.items = List.copyOf(items);
27	      this.totalWeight = WeightedRandom.getTotalWeight(items, Weighted::weight);
28	      if (this.totalWeight == 0) {
29	         this.selector = null;
30	      } else if (this.totalWeight < 64) {
31	         this.selector = new WeightedList.Flat<>(this.items, this.totalWeight);
