239	      } else {
240	         BlockTintSource tintSource = this.tintSources.set(tintIndex, null);
241	         if (tintSource != null) {
242	            int computedTintValue = tintSource.colorInWorld(state, level, pos);
243	            this.computedTintValues.set(tintIndex, computedTintValue);
244	            return computedTintValue;
245	         } else {
246	            return this.computedTintValues.getInt(tintIndex);
247	         }
248	      }
249	   }
