2	
3	import com.google.common.annotations.VisibleForTesting;
4	import com.mojang.blaze3d.platform.Transparency;
5	import com.mojang.math.MatrixUtil;
6	import com.mojang.math.Quadrant;
7	import com.mojang.math.Transformation;
8	import java.util.Objects;
9	import net.minecraft.client.model.geom.builders.UVPair;
10	import net.minecraft.client.renderer.FaceInfo;
11	import net.minecraft.client.renderer.block.dispatch.ModelState;
12	import net.minecraft.client.resources.model.ModelBaker;
13	import net.minecraft.client.resources.model.geometry.BakedQuad;
14	import net.minecraft.client.resources.model.sprite.Material;
15	import net.minecraft.core.Direction;
16	import org.joml.GeometryUtils;
17	import org.joml.Matrix4fc;
18	import org.joml.Vector3f;
19	import org.joml.Vector3fc;
20	import org.jspecify.annotations.Nullable;
21	
22	public class FaceBakery {
23	   private static final Vector3fc BLOCK_MIDDLE = new Vector3f(0.5F, 0.5F, 0.5F);
24	
25	   @VisibleForTesting
26	   static CuboidFace.UVs defaultFaceUV(final Vector3fc from, final Vector3fc to, final Direction facing) {
27	      return switch (facing) {
28	         case DOWN -> new CuboidFace.UVs(from.x(), 16.0F - to.z(), to.x(), 16.0F - from.z());
29	         case UP -> new CuboidFace.UVs(from.x(), from.z(), to.x(), to.z());
30	         case NORTH -> new CuboidFace.UVs(16.0F - to.x(), 16.0F - to.y(), 16.0F - from.x(), 16.0F - from.y());
31	         case SOUTH -> new CuboidFace.UVs(from.x(), 16.0F - to.y(), to.x(), 16.0F - from.y());
32	         case WEST -> new CuboidFace.UVs(from.z(), 16.0F - to.y(), to.z(), 16.0F - from.y());
33	         case EAST -> new CuboidFace.UVs(16.0F - to.z(), 16.0F - to.y(), 16.0F - from.z(), 16.0F - from.y());
34	      };
35	   }
36	
37	   private static Transparency computeMaterialTransparency(final Material.Baked material, final CuboidFace.UVs uvs) {
38	      return material.forceTranslucent()
39	         ? Transparency.TRANSLUCENT
40	         : material.sprite()
41	            .contents()
42	            .computeTransparency(
43	               Math.min(uvs.minU(), uvs.maxU()) / 16.0F,
44	               Math.min(uvs.minV(), uvs.maxV()) / 16.0F,
45	               Math.max(uvs.minU(), uvs.maxU()) / 16.0F,
46	               Math.max(uvs.minV(), uvs.maxV()) / 16.0F
47	            );
48	   }
49	
50	   public static BakedQuad bakeQuad(
51	      final ModelBaker modelBaker,
52	      final Vector3fc from,
53	      final Vector3fc to,
54	      final CuboidFace face,
55	      final Material.Baked material,
56	      final Direction facing,
57	      final ModelState modelState,
58	      final @Nullable CuboidRotation elementRotation,
59	      final boolean shade,
60	      final int lightEmission
61	   ) {
62	      CuboidFace.UVs uvs = face.uvs();
63	      if (uvs == null) {
64	         uvs = defaultFaceUV(from, to, facing);
65	      }
66	
67	      Transparency transparency = computeMaterialTransparency(material, uvs);
68	      ModelBaker.Interner interner = modelBaker.interner();
69	      BakedQuad.MaterialInfo materialInfo = interner.materialInfo(BakedQuad.MaterialInfo.of(material, transparency, face.tintIndex(), shade, lightEmission));
70	      return bakeQuad(interner, from, to, uvs, face.rotation(), materialInfo, facing, modelState, elementRotation);
71	   }
72	
73	   public static BakedQuad bakeQuad(
74	      final ModelBaker.Interner interner,
75	      final Vector3fc from,
76	      final Vector3fc to,
77	      final CuboidFace.UVs uvs,
78	      final Quadrant uvRotation,
79	      final BakedQuad.MaterialInfo materialInfo,
80	      final Direction facing,
81	      final ModelState modelState,
82	      final @Nullable CuboidRotation elementRotation
83	   ) {
84	      Matrix4fc uvTransform = modelState.inverseFaceTransformation(facing);
85	      Vector3fc[] vertexPositions = new Vector3fc[4];
86	      long[] vertexPackedUvs = new long[4];
87	      FaceInfo faceInfo = FaceInfo.fromFacing(facing);
88	
89	      for (int i = 0; i < 4; i++) {
90	         bakeVertex(
91	            i,
92	            faceInfo,
93	            uvs,
94	            uvRotation,
95	            uvTransform,
96	            from,
97	            to,
98	            materialInfo,
99	            modelState.transformation(),
100	            elementRotation,
101	            vertexPositions,
102	            vertexPackedUvs,
103	            interner
104	         );
105	      }
106	
107	      Direction finalDirection = calculateFacing(vertexPositions);
108	      if (elementRotation == null && finalDirection != null) {
109	         recalculateWinding(vertexPositions, vertexPackedUvs, finalDirection);
110	      }
111	
112	      return new BakedQuad(
113	         vertexPositions[0],
114	         vertexPositions[1],
115	         vertexPositions[2],
116	         vertexPositions[3],
117	         vertexPackedUvs[0],
118	         vertexPackedUvs[1],
119	         vertexPackedUvs[2],
120	         vertexPackedUvs[3],
121	         Objects.requireNonNullElse(finalDirection, Direction.UP),
122	         materialInfo
123	      );
124	   }
125	
126	   private static void bakeVertex(
127	      final int index,
128	      final FaceInfo faceInfo,
129	      final CuboidFace.UVs uvs,
130	      final Quadrant uvRotation,
131	      final Matrix4fc uvTransform,
132	      final Vector3fc from,
133	      final Vector3fc to,
134	      final BakedQuad.MaterialInfo materialInfo,
135	      final Transformation rotation,
136	      final @Nullable CuboidRotation elementRotation,
137	      final Vector3fc[] positionOutput,
138	      final long[] uvOutput,
139	      final ModelBaker.Interner interner
140	   ) {
141	      FaceInfo.VertexInfo vertexInfo = faceInfo.getVertexInfo(index);
142	      Vector3f vertex = vertexInfo.select(from, to).div(16.0F);
143	      if (elementRotation != null) {
144	         rotateVertexBy(vertex, elementRotation.origin(), elementRotation.transform());
145	      }
146	
147	      if (rotation != Transformation.IDENTITY) {
148	         rotateVertexBy(vertex, BLOCK_MIDDLE, rotation.getMatrix());
149	      }
150	
151	      float rawU = CuboidFace.getU(uvs, uvRotation, index);
152	      float rawV = CuboidFace.getV(uvs, uvRotation, index);
153	      float transformedV;
154	      float transformedU;
155	      if (MatrixUtil.isIdentity(uvTransform)) {
156	         transformedU = rawU;
157	         transformedV = rawV;
158	      } else {
159	         Vector3f transformedUV = uvTransform.transformPosition(new Vector3f(cornerToCenter(rawU), cornerToCenter(rawV), 0.0F));
160	         transformedU = centerToCorner(transformedUV.x);
161	         transformedV = centerToCorner(transformedUV.y);
162	      }
163	
164	      positionOutput[index] = interner.vector(vertex);
165	      uvOutput[index] = UVPair.pack(materialInfo.sprite().getU(transformedU), materialInfo.sprite().getV(transformedV));
166	   }
167	
168	   private static float cornerToCenter(final float value) {
169	      return value - 0.5F;
170	   }
171	
172	   private static float centerToCorner(final float value) {
173	      return value + 0.5F;
174	   }
175	
176	   private static void rotateVertexBy(final Vector3f vertex, final Vector3fc origin, final Matrix4fc transformation) {
177	      vertex.sub(origin);
178	      transformation.transformPosition(vertex);
179	      vertex.add(origin);
180	   }
181	
182	   private static @Nullable Direction calculateFacing(final Vector3fc[] positions) {
183	      Vector3f normal = new Vector3f();
184	      GeometryUtils.normal(positions[0], positions[1], positions[2], normal);
185	      return findClosestDirection(normal);
186	   }
187	
188	   private static @Nullable Direction findClosestDirection(final Vector3f direction) {
189	      if (!direction.isFinite()) {
190	         return null;
191	      } else {
192	         Direction best = null;
193	         float closestProduct = 0.0F;
194	
195	         for (Direction candidate : Direction.values()) {
196	            float product = direction.dot(candidate.getUnitVec3f());
197	            if (product >= 0.0F && product > closestProduct) {
198	               closestProduct = product;
199	               best = candidate;
200	            }
201	         }
202	
203	         return best;
204	      }
205	   }
206	
207	   private static void recalculateWinding(final Vector3fc[] positions, final long[] uvs, final Direction direction) {
208	      float minX = 999.0F;
209	      float minY = 999.0F;
210	      float minZ = 999.0F;
211	      float maxX = -999.0F;
212	      float maxY = -999.0F;
213	      float maxZ = -999.0F;
214	
215	      for (int i = 0; i < 4; i++) {
216	         Vector3fc position = positions[i];
217	         float x = position.x();
218	         float y = position.y();
219	         float z = position.z();
220	         if (x < minX) {
221	            minX = x;
222	         }
223	
224	         if (y < minY) {
225	            minY = y;
226	         }
227	
228	         if (z < minZ) {
229	            minZ = z;
230	         }
231	
232	         if (x > maxX) {
233	            maxX = x;
234	         }
235	
236	         if (y > maxY) {
237	            maxY = y;
238	         }
239	
240	         if (z > maxZ) {
241	            maxZ = z;
242	         }
243	      }
244	
245	      FaceInfo info = FaceInfo.fromFacing(direction);
246	
247	      for (int vertex = 0; vertex < 4; vertex++) {
248	         FaceInfo.VertexInfo vertInfo = info.getVertexInfo(vertex);
249	         float newX = vertInfo.xFace().select(minX, minY, minZ, maxX, maxY, maxZ);
250	         float newY = vertInfo.yFace().select(minX, minY, minZ, maxX, maxY, maxZ);
251	         float newZ = vertInfo.zFace().select(minX, minY, minZ, maxX, maxY, maxZ);
252	         int vertexToSwap = findVertex(positions, vertex, newX, newY, newZ);
253	         if (vertexToSwap == -1) {
254	            throw new IllegalStateException("Can't find vertex to swap");
255	         }
256	
257	         if (vertexToSwap != vertex) {
258	            swap(positions, vertexToSwap, vertex);
259	            swap(uvs, vertexToSwap, vertex);
260	         }
261	      }
262	   }
263	
264	   private static int findVertex(final Vector3fc[] positions, final int start, final float x, final float y, final float z) {
265	      for (int i = start; i < 4; i++) {
266	         Vector3fc position = positions[i];
267	         if (x == position.x() && y == position.y() && z == position.z()) {
268	            return i;
269	         }
270	      }
271	
272	      return -1;
273	   }
274	
275	   private static void swap(final Vector3fc[] array, final int indexA, final int indexB) {
276	      Vector3fc tmp = array[indexA];
277	      array[indexA] = array[indexB];
278	      array[indexB] = tmp;
279	   }
280	
281	   private static void swap(final long[] array, final int indexA, final int indexB) {
