         this.clientInfos,
         (location, clientInfo) -> {
            try {
               return clientInfo.model()
                  .bake(
                     new ItemModel.BakingContext(
                        baker, this.entityModelSet, this.sprites, this.playerSkinRenderCache, missingModels.item, clientInfo.registrySwapper()
