66	      boolean translucent3 = !corner3.isViewBlocking(level, pos) || corner3.getLightDampening() == 0;
67	      float shadeCorner02;
68	      int lightCorner02;
69	      if (!translucent2 && !translucent0) {
70	         shadeCorner02 = shade0;
