81	      if (!translucent3 && !translucent0) {
82	         shadeCorner03 = shade0;
83	         lightCorner03 = light0;
84	      } else {
85	         pos.setWithOffset(basePosition, info.corners[0]).move(info.corners[3]);
86	         BlockState state03 = level.getBlockState(pos);
87	         shadeCorner03 = this.cache.getShadeBrightness(state03, level, pos);
88	         lightCorner03 = this.cache.getLightCoords(state03, level, pos);
89	      }
90	
91	      float shadeCorner12;
92	      int lightCorner12;
93	      if (!translucent2 && !translucent1) {
94	         shadeCorner12 = shade0;
95	         lightCorner12 = light0;
96	      } else {
97	         pos.setWithOffset(basePosition, info.corners[1]).move(info.corners[2]);
98	         BlockState state12 = level.getBlockState(pos);
99	         shadeCorner12 = this.cache.getShadeBrightness(state12, level, pos);
100	         lightCorner12 = this.cache.getLightCoords(state12, level, pos);
