104	      int lightCorner13;
105	      if (!translucent3 && !translucent1) {
106	         shadeCorner13 = shade0;
107	         lightCorner13 = light0;
108	      } else {
109	         pos.setWithOffset(basePosition, info.corners[1]).move(info.corners[3]);
110	         BlockState state13 = level.getBlockState(pos);
