198	   public void prepareQuadFlat(
199	      final BlockAndTintGetter level,
200	      final BlockState state,
201	      final BlockPos pos,
202	      final int lightCoords,
203	      final BakedQuad quad,
204	      final QuadInstance outputInstance
205	   ) {
206	      if (lightCoords == -1) {
207	         this.prepareQuadShape(level, state, pos, quad, false);
208	         BlockPos lightPos = (BlockPos)(this.faceCubic ? this.scratchPos.setWithOffset(pos, quad.direction()) : pos);
209	         outputInstance.setLightCoords(this.cache.getLightCoords(state, level, lightPos));
210	      } else {
211	         outputInstance.setLightCoords(lightCoords);
212	      }
213	
214	      CardinalLighting cardinalLighting = level.cardinalLighting();
215	      float directionalBrightness = quad.materialInfo().shade() ? cardinalLighting.byFace(quad.direction()) : cardinalLighting.up();
216	      outputInstance.setColor(ARGB.gray(directionalBrightness));
217	   }
