219	   private void prepareQuadShape(
220	      final BlockAndTintGetter level, final BlockState state, final BlockPos pos, final BakedQuad quad, final boolean ambientOcclusion
221	   ) {
222	      float minX = 32.0F;
223	      float minY = 32.0F;
224	      float minZ = 32.0F;
225	      float maxX = -32.0F;
226	      float maxY = -32.0F;
227	      float maxZ = -32.0F;
228	
229	      for (int i = 0; i < 4; i++) {
230	         Vector3fc position = quad.position(i);
231	         float x = position.x();
232	         float y = position.y();
233	         float z = position.z();
234	         minX = Math.min(minX, x);
235	         minY = Math.min(minY, y);
236	         minZ = Math.min(minZ, z);
237	         maxX = Math.max(maxX, x);
238	         maxY = Math.max(maxY, y);
239	         maxZ = Math.max(maxZ, z);
240	      }
241	
242	      if (ambientOcclusion) {
243	         this.faceShape[BlockModelLighter.SizeInfo.WEST.index] = minX;
244	         this.faceShape[BlockModelLighter.SizeInfo.EAST.index] = maxX;
245	         this.faceShape[BlockModelLighter.SizeInfo.DOWN.index] = minY;
246	         this.faceShape[BlockModelLighter.SizeInfo.UP.index] = maxY;
247	         this.faceShape[BlockModelLighter.SizeInfo.NORTH.index] = minZ;
248	         this.faceShape[BlockModelLighter.SizeInfo.SOUTH.index] = maxZ;
249	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_WEST.index] = 1.0F - minX;
250	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_EAST.index] = 1.0F - maxX;
251	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_DOWN.index] = 1.0F - minY;
252	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_UP.index] = 1.0F - maxY;
253	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_NORTH.index] = 1.0F - minZ;
254	         this.faceShape[BlockModelLighter.SizeInfo.FLIP_SOUTH.index] = 1.0F - maxZ;
255	      }
256	
257	      float minEpsilon = 1.0E-4F;
258	      float maxEpsilon = 0.9999F;
259	
260	      this.facePartial = switch (quad.direction()) {
261	         case DOWN, UP -> minX >= 1.0E-4F || minZ >= 1.0E-4F || maxX <= 0.9999F || maxZ <= 0.9999F;
262	         case NORTH, SOUTH -> minX >= 1.0E-4F || minY >= 1.0E-4F || maxX <= 0.9999F || maxY <= 0.9999F;
263	         case WEST, EAST -> minY >= 1.0E-4F || minZ >= 1.0E-4F || maxY <= 0.9999F || maxZ <= 0.9999F;
264	      };
265	
266	      this.faceCubic = switch (quad.direction()) {
267	         case DOWN -> minY == maxY && (minY < 1.0E-4F || state.isCollisionShapeFullBlock(level, pos));
268	         case UP -> minY == maxY && (maxY > 0.9999F || state.isCollisionShapeFullBlock(level, pos));
269	         case NORTH -> minZ == maxZ && (minZ < 1.0E-4F || state.isCollisionShapeFullBlock(level, pos));
270	         case SOUTH -> minZ == maxZ && (maxZ > 0.9999F || state.isCollisionShapeFullBlock(level, pos));
271	         case WEST -> minX == maxX && (minX < 1.0E-4F || state.isCollisionShapeFullBlock(level, pos));
272	         case EAST -> minX == maxX && (maxX > 0.9999F || state.isCollisionShapeFullBlock(level, pos));
273	      };
274	   }
275	
276	   public static void enableCaching() {
277	      CACHE.get().enable();
278	   }
279	
280	   public static void clearCache() {
281	      CACHE.get().disable();
282	   }
283	
284	   private static enum AdjacencyInfo {
285	      DOWN(
286	         new Direction[]{Direction.WEST, Direction.EAST, Direction.NORTH, Direction.SOUTH},
287	         0.5F,
288	         true,
289	         new BlockModelLighter.SizeInfo[]{
290	            BlockModelLighter.SizeInfo.FLIP_WEST,
291	            BlockModelLighter.SizeInfo.SOUTH,
292	            BlockModelLighter.SizeInfo.FLIP_WEST,
293	            BlockModelLighter.SizeInfo.FLIP_SOUTH,
294	            BlockModelLighter.SizeInfo.WEST,
295	            BlockModelLighter.SizeInfo.FLIP_SOUTH,
296	            BlockModelLighter.SizeInfo.WEST,
297	            BlockModelLighter.SizeInfo.SOUTH
298	         },
299	         new BlockModelLighter.SizeInfo[]{
300	            BlockModelLighter.SizeInfo.FLIP_WEST,
301	            BlockModelLighter.SizeInfo.NORTH,
302	            BlockModelLighter.SizeInfo.FLIP_WEST,
303	            BlockModelLighter.SizeInfo.FLIP_NORTH,
304	            BlockModelLighter.SizeInfo.WEST,
305	            BlockModelLighter.SizeInfo.FLIP_NORTH,
306	            BlockModelLighter.SizeInfo.WEST,
307	            BlockModelLighter.SizeInfo.NORTH
308	         },
309	         new BlockModelLighter.SizeInfo[]{
310	            BlockModelLighter.SizeInfo.FLIP_EAST,
311	            BlockModelLighter.SizeInfo.NORTH,
312	            BlockModelLighter.SizeInfo.FLIP_EAST,
313	            BlockModelLighter.SizeInfo.FLIP_NORTH,
