121	function defaultSound(name) {
122	  if (name === 'grass_block' || name === 'moss_block' || name.includes('leaves') || name === 'short_grass' || name === 'fern' ||
123	    name === 'dead_bush' || /^(poppy|dandelion|cornflower|azure_bluet|oxeye_daisy|allium|lily_of_the_valley)$/.test(name)) return 'grass';
124	  if (name.includes('log') || name.includes('planks') || name.includes('stairs') || name.includes('slab') ||
125	    name === 'bookshelf' || name === 'crafting_table' || name === 'torch') return 'wood';
126	  if (name === 'sand' || name === 'red_sand' || name === 'sandstone' || name === 'red_sandstone') return 'sand';
127	  if (name === 'dirt' || name === 'coarse_dirt' || name === 'rooted_dirt' || name === 'podzol' || name === 'gravel' || name === 'clay') return 'gravel';
128	  if (name === 'snow' || name === 'snow_block') return 'snow';
129	  if (name === 'glass' || name === 'ice' || name === 'glowstone' || name === 'sea_lantern') return 'glass';
130	  if (name === 'cactus' || name === 'wool') return 'wool';
131	  if (name === 'lantern') return 'lantern';
132	  if (name === 'water') return 'water';
133	  if (name === 'lava') return 'lava';
134	  return 'stone';
135	}
136	
137	const DEFAULT_STATE = {
138	  grass_block: 'snowy=false', podzol: 'snowy=false', oak_log: 'axis=y', birch_log: 'axis=y', spruce_log: 'axis=y',
139	  snow: 'layers=1', oak_stairs: 'facing=east,half=bottom,shape=straight', birch_stairs: 'facing=east,half=bottom,shape=straight',
140	  spruce_stairs: 'facing=east,half=bottom,shape=straight', oak_slab: 'type=bottom', birch_slab: 'type=bottom', spruce_slab: 'type=bottom',
141	  lantern: 'hanging=false', sulfur_spike: 'thickness=base,vertical_direction=up', water: 'level=0', lava: 'level=0',
142	};
143	
144	function normModelName(name) {
145	  return name.replace(/^minecraft:/, '').replace(/^models\//, '');
146	}
147	function normTextureName(name) {
148	  return name.replace(/^minecraft:/, '').replace(/^textures\//, '');
149	}
150	
151	const modelCache = new Map();
152	async function loadModel(name) {
153	  name = normModelName(name);
154	  if (modelCache.has(name)) return modelCache.get(name);
155	  const p = path.join(SRC, 'models', name + '.json');
156	  if (!existsSync(p)) throw new Error('missing model ' + name);
157	  const raw = JSON.parse(await fs.readFile(p, 'utf8'));
158	  const base = raw.parent ? await loadModel(raw.parent) : { textures: {}, elements: [], ao: true, guiLight: 'side' };
159	  const merged = {
160	    textures: { ...base.textures, ...(raw.textures || {}) },
161	    elements: raw.elements ?? base.elements,
162	    ao: raw.ambientocclusion ?? base.ao,
163	    guiLight: raw.gui_light ?? base.guiLight,
164	    display: raw.display ?? base.display,
165	  };
166	  modelCache.set(name, merged);
167	  return merged;
168	}
169	
170	function resolveTexture(ref, textures, depth = 0) {
171	  if (depth > 16) throw new Error('texture reference loop: ' + JSON.stringify(ref));
172	  if (ref && typeof ref === 'object') {
173	    if (typeof ref.sprite !== 'string') throw new Error('bad sprite reference: ' + JSON.stringify(ref));
174	    const inner = resolveTexture(ref.sprite, textures, depth + 1);
175	    return { key: inner.key, tr: inner.tr || ref.force_translucent === true };
176	  }
177	  if (typeof ref !== 'string') throw new Error('bad texture reference: ' + JSON.stringify(ref));
178	  if (ref.startsWith('#')) {
179	    const key = ref.slice(1);
180	    if (!(key in textures)) throw new Error('unknown texture variable ' + ref);
181	    return resolveTexture(textures[key], textures, depth + 1);
182	  }
183	  return { key: normTextureName(ref), tr: false };
184	}
185	
186	function rotatePoint(p, axis, degrees, origin) {
187	  if (!degrees) return p;
188	  const a = (degrees * Math.PI) / 180;
189	  const c = Math.cos(a), s = Math.sin(a);
190	  let [x, y, z] = p;
191	  const [ox, oy, oz] = origin;
192	  x -= ox; y -= oy; z -= oz;
193	  if (axis === 'x') { const ny = y * c - z * s; const nz = y * s + z * c; y = ny; z = nz; }
194	  else if (axis === 'y') { const nx = x * c + z * s; const nz = -x * s + z * c; x = nx; z = nz; }
195	  else { const nx = x * c - y * s; const ny = x * s + y * c; x = nx; y = ny; }
196	  return [x + ox, y + oy, z + oz];
197	}
198	
199	function autoUV(dir, from, to) {
200	  const [x1, y1, z1] = from, [x2, y2, z2] = to;
201	  switch (dir) {
202	    case 'down': return [x1, 16 - z2, x2, 16 - z1];
203	    case 'up': return [x1, z1, x2, z2];
204	    case 'north': return [16 - x2, 16 - y2, 16 - x1, 16 - y1];
205	    case 'south': return [x1, 16 - y2, x2, 16 - y1];
206	    case 'west': return [z1, 16 - y2, z2, 16 - y1];
207	    case 'east': return [16 - z2, 16 - y2, 16 - z1, 16 - y1];
208	  }
209	  return [0, 0, 16, 16];
210	}
211	
212	// World-space corners, ordered top-left, bottom-left, bottom-right, top-right
213	// as seen from outside the face. Returns corners plus UV corner flags.
214	function faceCorners(dir, from, to) {
215	  const [x1, y1, z1] = from, [x2, y2, z2] = to;
216	  switch (dir) {
217	    case 'south': return [[x1, y2, z2], [x1, y1, z2], [x2, y1, z2], [x2, y2, z2]];
218	    case 'north': return [[x2, y2, z1], [x2, y1, z1], [x1, y1, z1], [x1, y2, z1]];
219	    case 'east': return [[x2, y2, z2], [x2, y1, z2], [x2, y1, z1], [x2, y2, z1]];
220	    case 'west': return [[x1, y2, z1], [x1, y1, z1], [x1, y1, z2], [x1, y2, z2]];
221	    case 'up': return [[x1, y2, z1], [x1, y2, z2], [x2, y2, z2], [x2, y2, z1]];
222	    case 'down': return [[x1, y1, z2], [x1, y1, z1], [x2, y1, z1], [x2, y1, z2]];
223	  }
224	  throw new Error('bad dir ' + dir);
225	}
226	
227	function rotateUv([u1, v1, u2, v2], rot) {
228	  rot = ((rot % 360) + 360) % 360;
229	  if (rot === 90) return [u2, v1, u2, v2, u1, v2, u1, v1];
230	  if (rot === 180) return [u2, v2, u1, v2, u1, v1, u2, v1];
231	  if (rot === 270) return [u1, v2, u1, v1, u2, v1, u2, v2];
232	  return [u1, v1, u1, v2, u2, v2, u2, v1];
233	}
234	
235	function bakeModel(model, variantRot) {
236	  const quads = [];
237	  for (const el of model.elements) {
238	    const from = el.from.map(Number);
239	    const to = el.to.map(Number);
240	    const elRot = el.rotation;
241	    for (const dir of DIRS) {
242	      const face = el.faces?.[dir];
243	      if (!face || !face.texture) continue;
244	      let corners = faceCorners(dir, from, to);
245	      if (elRot) {
246	        corners = corners.map(c => rotatePoint(c, elRot.axis, Number(elRot.angle) || 0, elRot.origin || [8, 8, 8]));
247	      }
248	      if (variantRot) {
249	        corners = corners.map(c => {
250	          let p = rotatePoint(c, 'y', variantRot.y || 0, [8, 8, 8]);
251	          p = rotatePoint(p, 'x', variantRot.x || 0, [8, 8, 8]);
252	          return p;
253	        });
254	      }
255	      const uv = Array.isArray(face.uv) ? face.uv.map(Number) : autoUV(dir, from, to);
256	      const uvOrdered = rotateUv(uv, Number(face.rotation) || 0);
257	      const tex = resolveTexture(face.texture, model.textures);
258	      quads.push({
259	        p: corners.flat().map(v => Math.round((v / 16) * 10000) / 10000),
260	        uv: uvOrdered,
261	        t: tex.key,
262	        tr: tex.tr || undefined,
263	        d: DIR_INDEX[dir],
264	        c: face.cullface ? DIR_INDEX[face.cullface] : -1,
265	        ti: face.tintindex ?? -1,
266	        s: face.shade !== false && el.shade !== false,
267	        ao: model.ao !== false,
268	      });
269	    }
270	  }
271	  return quads;
272	}
273	
274	async function resolveBlockState(entry) {
275	  const bsPath = path.join(SRC, 'blockstates', entry.name + '.json');
276	  const bs = JSON.parse(await fs.readFile(bsPath, 'utf8'));
277	  if (!bs.variants) throw new Error(`${entry.name}: multipart blockstates are not supported yet`);
278	  const wanted = entry.state ?? DEFAULT_STATE[entry.name];
279	  let key = wanted;
280	  if (key == null || !(key in bs.variants)) key = Object.keys(bs.variants)[0];
281	  if (!(key in bs.variants)) throw new Error(`${entry.name}: no variants`);
282	  let variant = bs.variants[key];
283	  if (Array.isArray(variant)) variant = variant[0];
284	  if (!variant || !variant.model) throw new Error(`${entry.name}: bad variant ${key}`);
285	  const model = await loadModel(variant.model);
286	  const variantRot = (variant.x || variant.y) ? { x: Number(variant.x) || 0, y: Number(variant.y) || 0 } : null;
287	  return { key, quads: bakeModel(model, variantRot), guiLight: model.guiLight };
288	}
