290	async function pngSize(file) {
291	  const fd = await fs.open(file, 'r');
292	  const buf = Buffer.alloc(24);
293	  await fd.read(buf, 0, 24, 0);
294	  await fd.close();
295	  if (buf.readUInt32BE(0) !== 0x89504e47) throw new Error('not a png: ' + file);
296	  return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
297	}
298	
299	async function readAnim(file) {
300	  const metaPath = file + '.mcmeta';
301	  if (!existsSync(metaPath)) return null;
302	  const meta = JSON.parse(await fs.readFile(metaPath, 'utf8'));
303	  if (!meta.animation) return null;
304	  const a = meta.animation;
305	  const size = await pngSize(file);
306	  const frames = Math.max(1, Math.floor(size.h / size.w));
307	  return {
308	    frametime: a.frametime ?? 1,
309	    frames,
310	    frameList: a.frames ?? null,
311	    interpolate: !!a.interpolate,
312	    width: size.w,
313	  };
314	}
