317	const SOUND_EVENTS = [
318	  'block.stone.step', 'block.stone.break', 'block.stone.place',
319	  'block.grass.step', 'block.grass.break', 'block.grass.place',
320	  'block.wood.step', 'block.wood.break', 'block.wood.place',
321	  'block.sand.step', 'block.sand.break', 'block.sand.place',
322	  'block.gravel.step', 'block.gravel.break', 'block.gravel.place',
323	  'block.glass.step', 'block.glass.break', 'block.glass.place',
324	  'block.snow.step', 'block.snow.break', 'block.snow.place',
325	  'block.wool.step', 'block.wool.break', 'block.wool.place',
326	  'ui.button.click', 'block.water.ambient', 'ambient.underwater.enter', 'ambient.underwater.exit',
327	];
