329	async function buildSounds() {
330	  const ext = process.env.MC_EXTERNAL || 'C:/Users/zht/AppData/Roaming/.minecraft/assets';
331	  const idxPath = path.join(ext, 'indexes', '32.json');
332	  if (!existsSync(idxPath)) { console.warn('sound index not found:', idxPath); return { events: {} }; }
333	  const index = JSON.parse(await fs.readFile(idxPath, 'utf8')).objects;
334	  const soundsObj = index['minecraft/sounds.json'];
335	  if (!soundsObj) return { events: {} };
336	  const soundsJsonPath = path.join(ext, 'objects', soundsObj.hash.slice(0, 2), soundsObj.hash);
337	  const soundsData = JSON.parse(await fs.readFile(soundsJsonPath, 'utf8'));
338	  const events = {};
339	  let copied = 0;
340	  for (const event of SOUND_EVENTS) {
341	    const entry = soundsData[event];
342	    if (!entry) continue;
343	    const list = Array.isArray(entry.sounds) ? entry.sounds : [entry.sounds];
344	    const recs = [];
345	    for (const raw of list) {
346	      const name = typeof raw === 'string' ? raw : raw?.name;
347	      if (!name) continue;
348	      const objectKey = 'minecraft/sounds/' + (name.endsWith('.ogg') ? name : name + '.ogg');
349	      const obj = index[objectKey];
350	      if (!obj) continue;
351	      const src = path.join(ext, 'objects', obj.hash.slice(0, 2), obj.hash);
352	      if (!existsSync(src)) continue;
353	      const base = path.basename(objectKey);
354	      const destRel = path.posix.join('sounds', event, base);
355	      await fs.mkdir(path.dirname(path.join(OUT, destRel)), { recursive: true });
356	      await fs.copyFile(src, path.join(OUT, destRel));
357	      copied++;
358	      const rec = { path: '/mc/' + destRel, volume: 1, pitch: 1, weight: 1 };
359	      if (raw && typeof raw === 'object') {
360	        if (raw.volume != null) rec.volume = Number(raw.volume);
361	        if (raw.pitch != null) rec.pitch = Number(raw.pitch);
362	        if (raw.weight != null) rec.weight = Number(raw.weight);
363	      }
364	      if (entry.volume != null) rec.volume *= Number(entry.volume);
365	      if (entry.pitch != null) rec.pitch *= Number(entry.pitch);
366	      recs.push(rec);
367	    }
368	    if (recs.length) events[event] = recs;
369	  }
370	  console.log('sounds:', Object.keys(events).length, 'events,', copied, 'files');
371	  return { events };
372	}
373	
374	async function copyTree(src, dst) {
375	  if (!existsSync(src)) { console.warn('skip missing', src); return; }
376	  await fs.cp(src, dst, { recursive: true });
377	}
