379	// The extracted vanilla asset tree ships 1x1 placeholders for the title panorama.
380	// A real 26.2 client stores the six 1024x1024 faces in the assets object store;
381	// copy those official faces (never from the network) when they are available.
382	async function copyMenuAssets() {
383	  const ext = process.env.MC_EXTERNAL || 'C:/Users/zht/AppData/Roaming/.minecraft/assets';
384	  const idxDir = path.join(ext, 'indexes');
385	  const objDir = path.join(ext, 'objects');
386	  const faces = [];
387	  if (existsSync(idxDir) && existsSync(objDir)) {
388	    let index = null;
389	    let indexName = null;
390	    for (const file of (await fs.readdir(idxDir)).filter(f => f.endsWith('.json')).sort().reverse()) {
391	      try {
392	        const data = JSON.parse(await fs.readFile(path.join(idxDir, file), 'utf8'));
393	        if (data?.objects?.['minecraft/textures/gui/title/background/panorama_0.png']) {
394	          index = data;
395	          indexName = file;
396	          break;
397	        }
398	      } catch { /* ignore broken indexes */ }
399	    }
400	    if (index) {
401	      for (let i = 0; i < 6; i++) {
402	        const rel = `minecraft/textures/gui/title/background/panorama_${i}.png`;
403	        const rec = index.objects[rel];
404	        if (!rec) break;
405	        const src = path.join(objDir, rec.hash.slice(0, 2), rec.hash);
406	        if (!existsSync(src)) break;
407	        const size = await pngSize(src);
408	        if (size.w < 16 || size.h < 16) break;
409	        const outRel = path.posix.join('gui/title/background', `panorama_${i}.png`);
410	        await fs.mkdir(path.dirname(path.join(OUT, outRel)), { recursive: true });
411	        await fs.copyFile(src, path.join(OUT, outRel));
412	        faces.push(`${size.w}x${size.h}`);
413	      }
414	      if (faces.length === 6) console.log('menu panorama: 6 official faces from assets index', indexName, faces.join(', '));
415	      else console.warn('menu panorama: only found', faces.length, 'usable faces in assets index');
416	    } else {
417	      console.warn('menu panorama: assets index with panorama not found');
418	    }
419	  } else {
420	    console.warn('menu panorama: official assets store not found at', ext);
421	  }
422	
423	  // Official splash lines for the main menu.
424	  const splashSrc = path.join(SRC, 'texts/splashes.txt');
425	  if (existsSync(splashSrc)) {
426	    await fs.mkdir(path.join(OUT, 'texts'), { recursive: true });
427	    await fs.copyFile(splashSrc, path.join(OUT, 'texts/splashes.txt'));
428	  } else {
429	    console.warn('menu splashes: missing', splashSrc);
430	  }
431	}
432	
433	async function main() {
434	  if (!existsSync(SRC)) throw new Error('MC assets not found: ' + SRC);
435	  await fs.rm(OUT, { recursive: true, force: true });
436	  await fs.mkdir(OUT, { recursive: true });
437	
438	  const blocks = [];
439	  const textureRefs = new Map(); // key -> {src}
440	  let id = 1;
441	  for (const entry of PALETTE) {
442	    const flags = { ...blockMetaDefaults, ...(entry.flags || {}) };
443	    if (!(entry.flags && entry.flags.sound)) flags.sound = defaultSound(entry.name);
444	    if (entry.tint) flags.tint = entry.tint;
445	    if (entry.tintColor) flags.tintColor = entry.tintColor;
446	    let stateKey = entry.state ?? DEFAULT_STATE[entry.name] ?? '';
447	    let quads = [];
448	    let guiLight = 'side';
449	    if (!entry.custom) {
450	      const resolved = await resolveBlockState(entry).catch(err => { throw new Error(`${entry.name}: ${err.message}`); });
451	      stateKey = resolved.key;
452	      quads = resolved.quads;
453	      guiLight = resolved.guiLight;
454	      for (const q of quads) textureRefs.set(q.t, { src: path.join(SRC, 'textures', q.t + '.png') });
455	      if (quads.some(q => q.tr)) flags.render = 'translucent';
456	      if (!quads.length) throw new Error('no geometry: ' + entry.name);
457	    } else if (entry.custom === 'water' || entry.custom === 'lava') {
458	      textureRefs.set(`block/${entry.name}_still`, { src: path.join(SRC, 'textures', `block/${entry.name}_still.png`) });
459	    }
460	    blocks.push({
461	      id: id++,
462	      name: entry.name,
463	      state: stateKey,
464	      guiLight,
465	      custom: entry.custom || null,
466	      flags,
467	      quads,
468	    });
469	  }
470	
471	  // Extra textures the renderer needs directly.
472	  for (let i = 0; i < 10; i++) textureRefs.set(`block/destroy_stage_${i}`, { src: path.join(SRC, `textures/block/destroy_stage_${i}.png`) });
473	
474	  const textures = {};
475	  const animTextures = [];
476	  let layerCount = 0;
477	  for (const [key, info] of [...textureRefs.entries()].sort(([a], [b]) => a.localeCompare(b))) {
478	    if (!existsSync(info.src)) throw new Error('missing texture ' + key + ' -> ' + info.src);
479	    const size = await pngSize(info.src);
480	    const anim = await readAnim(info.src);
481	    const frames = anim ? Math.max(1, Math.floor(size.h / size.w)) : 1;
482	    const outRel = path.posix.join('textures', key + '.png');
483	    await fs.mkdir(path.dirname(path.join(OUT, outRel)), { recursive: true });
484	    await fs.copyFile(info.src, path.join(OUT, outRel));
485	    const metaSrc = info.src + '.mcmeta';
486	    if (existsSync(metaSrc)) await fs.copyFile(metaSrc, path.join(OUT, outRel + '.mcmeta'));
487	    const arrayable = size.w === 16 && size.h === 16 * frames;
488	    const framePaths = [];
489	    if (arrayable && anim && frames > 1) {
490	      const full = PNG.sync.read(await fs.readFile(info.src));
491	      for (let f = 0; f < frames; f++) {
492	        const frame = new PNG({ width: 16, height: 16 });
493	        for (let y = 0; y < 16; y++) {
494	          const srcStart = ((f * 16 + y) * full.width) * 4;
495	          const dstStart = (y * 16) * 4;
496	          full.data.copy(frame.data, dstStart, srcStart, srcStart + 16 * 4);
497	        }
498	        const frameRel = path.posix.join('textures', `${key}.${f}.png`);
499	        await fs.writeFile(path.join(OUT, frameRel), PNG.sync.write(frame));
500	        framePaths.push('/' + path.posix.join(path.basename(OUT), frameRel));
501	      }
502	    } else {
503	      framePaths.push('/' + path.posix.join(path.basename(OUT), outRel));
504	    }
505	    const rec = {
506	      key,
507	      path: '/' + path.posix.join(path.basename(OUT), outRel),
508	      framePaths,
509	      w: size.w, h: size.h,
510	      animated: !!anim,
511	      animation: anim,
512	      frames,
513	      animId: -1,
514	      arrayLayer: arrayable ? layerCount : -1,
515	    };
516	    if (arrayable) {
517	      if (anim) {
518	        rec.animId = animTextures.length;
519	        animTextures.push({ id: rec.animId, key, layer: layerCount, frames, frametime: anim.frametime, frameList: anim.frameList, interpolate: anim.interpolate });
520	      }
521	      layerCount += frames;
522	    }
523	    textures[key] = rec;
524	  }
525	
526	  // Environment, GUI, font, misc, colormap, particles.
527	  await copyTree(path.join(SRC, 'textures/gui'), path.join(OUT, 'gui'));
528	  await copyTree(path.join(SRC, 'textures/environment'), path.join(OUT, 'environment'));
529	  await copyTree(path.join(SRC, 'textures/misc'), path.join(OUT, 'misc'));
530	  await copyTree(path.join(SRC, 'textures/colormap'), path.join(OUT, 'colormap'));
531	  await copyTree(path.join(SRC, 'textures/particle'), path.join(OUT, 'particle'));
532	  await copyTree(path.join(SRC, 'textures/font'), path.join(OUT, 'font/textures'));
533	  await copyTree(path.join(SRC, 'font'), path.join(OUT, 'font/meta'));
534	  await copyMenuAssets();
535	
536	  const audio = await buildSounds();
537	
538	  const manifest = {
539	    generatedAt: new Date().toISOString(),
540	    audio,
541	    version: '26.2',
542	    textures,
543	    layerCount,
544	    animTextures,
545	    blocks,
546	    gui: {
547	      hotbar: '/mc/gui/sprites/hud/hotbar.png',
548	      hotbarSelection: '/mc/gui/sprites/hud/hotbar_selection.png',
549	      crosshair: '/mc/gui/sprites/hud/crosshair.png',
550	      hotbarOffhandLeft: '/mc/gui/sprites/hud/hotbar_offhand_left.png',
551	      hotbarOffhandRight: '/mc/gui/sprites/hud/hotbar_offhand_right.png',
552	      experienceBar: '/mc/gui/sprites/hud/experience_bar_background.png',
553	      experienceProgress: '/mc/gui/sprites/hud/experience_bar_progress.png',
554	    },
555	    environment: {
556	      sun: '/mc/environment/celestial/sun.png',
557	      moon: '/mc/environment/celestial/moon',
558	      clouds: '/mc/environment/clouds.png',
559	      rain: '/mc/environment/rain.png',
560	      snow: '/mc/environment/snow.png',
561	      underwater: '/mc/misc/underwater.png',
562	      vignette: '/mc/misc/vignette.png',
563	    },
564	    colormap: {
565	      grass: '/mc/colormap/grass.png',
566	      foliage: '/mc/colormap/foliage.png',
567	    },
568	    font: {
569	      defaultJson: '/mc/font/meta/default.json',
570	      ascii: '/mc/font/textures/ascii.png',
571	      accented: '/mc/font/textures/accented.png',
572	      nonlatin: '/mc/font/textures/nonlatin_european.png',
573	    },
574	  };
575	  await fs.writeFile(path.join(OUT, 'manifest.json'), JSON.stringify(manifest));
576	  const animated = animTextures.map(t => `${t.key}(${t.frames}f/${t.frametime}t)`);
577	  console.log(`blocks=${blocks.length} textures=${Object.keys(textures).length} arrayLayers=${layerCount}`);
578	  console.log('animated:', animated.join(', ') || 'none');
579	  const bad = Object.values(textures).filter(t => t.arrayLayer < 0);
580	  console.log('non-arrayable:', bad.map(t => `${t.key} ${t.w}x${t.h}`).join(', ') || 'none');
581	}
582	
583	main().catch(err => { console.error(err); process.exit(1); });
