1	package net.minecraft.client.resources.model.cuboid;
2	
3	import com.mojang.math.Quadrant;
4	import java.util.Collection;
5	import java.util.HashSet;
6	import java.util.List;
7	import java.util.Set;
8	import net.minecraft.client.renderer.block.dispatch.ModelState;
9	import net.minecraft.client.renderer.texture.SpriteContents;
10	import net.minecraft.client.resources.model.ModelBaker;
11	import net.minecraft.client.resources.model.ModelDebugName;
12	import net.minecraft.client.resources.model.UnbakedModel;
13	import net.minecraft.client.resources.model.geometry.BakedQuad;
14	import net.minecraft.client.resources.model.geometry.QuadCollection;
15	import net.minecraft.client.resources.model.geometry.UnbakedGeometry;
16	import net.minecraft.client.resources.model.sprite.Material;
17	import net.minecraft.client.resources.model.sprite.TextureSlots;
18	import net.minecraft.core.Direction;
19	import net.minecraft.resources.Identifier;
20	import org.joml.Vector3f;
21	import org.jspecify.annotations.Nullable;
22	
23	public class ItemModelGenerator implements UnbakedModel {
24	   public static final Identifier GENERATED_ITEM_MODEL_ID = Identifier.withDefaultNamespace("builtin/generated");
25	   public static final List<String> LAYERS = List.of("layer0", "layer1", "layer2", "layer3", "layer4");
26	   private static final float MIN_Z = 7.5F;
27	   private static final float MAX_Z = 8.5F;
28	   private static final TextureSlots.Data TEXTURE_SLOTS = new TextureSlots.Data.Builder().addReference("particle", "layer0").build();
29	   private static final CuboidFace.UVs SOUTH_FACE_UVS = new CuboidFace.UVs(0.0F, 0.0F, 16.0F, 16.0F);
30	   private static final CuboidFace.UVs NORTH_FACE_UVS = new CuboidFace.UVs(16.0F, 0.0F, 0.0F, 16.0F);
31	   private static final float UV_SHRINK = 0.1F;
32	
33	   @Override
34	   public TextureSlots.Data textureSlots() {
35	      return TEXTURE_SLOTS;
36	   }
37	
38	   @Override
39	   public UnbakedGeometry geometry() {
40	      return ItemModelGenerator::bake;
41	   }
42	
43	   @Override
44	   public UnbakedModel.@Nullable GuiLight guiLight() {
45	      return UnbakedModel.GuiLight.FRONT;
46	   }
47	
48	   private static QuadCollection bake(final TextureSlots textureSlots, final ModelBaker modelBaker, final ModelState modelState, final ModelDebugName name) {
49	      QuadCollection singleResult = null;
50	      QuadCollection.Builder builder = null;
51	
52	      for (int layerIndex = 0; layerIndex < LAYERS.size(); layerIndex++) {
53	         String textureReference = LAYERS.get(layerIndex);
54	         Material material = textureSlots.getMaterial(textureReference);
55	         if (material == null) {
56	            break;
57	         }
58	
59	         Material.Baked bakedMaterial = modelBaker.materials().get(material, name);
60	         QuadCollection bakedLayer = modelBaker.compute(new ItemModelGenerator.ItemLayerKey(bakedMaterial, modelState, layerIndex));
61	         if (builder != null) {
62	            builder.addAll(bakedLayer);
63	         } else if (singleResult != null) {
64	            builder = new QuadCollection.Builder();
65	            builder.addAll(singleResult);
66	            builder.addAll(bakedLayer);
67	            singleResult = null;
68	         } else {
69	            singleResult = bakedLayer;
70	         }
71	      }
72	
73	      if (builder != null) {
74	         return builder.build();
75	      } else {
76	         return singleResult != null ? singleResult : QuadCollection.EMPTY;
77	      }
78	   }
79	
80	   private static void bakeExtrudedSprite(
81	      final QuadCollection.Builder builder, final ModelBaker.Interner interner, final ModelState modelState, final BakedQuad.MaterialInfo materialInfo
82	   ) {
83	      Vector3f from = new Vector3f(0.0F, 0.0F, 7.5F);
84	      Vector3f to = new Vector3f(16.0F, 16.0F, 8.5F);
85	      builder.addUnculledFace(FaceBakery.bakeQuad(interner, from, to, SOUTH_FACE_UVS, Quadrant.R0, materialInfo, Direction.SOUTH, modelState, null));
86	      builder.addUnculledFace(FaceBakery.bakeQuad(interner, from, to, NORTH_FACE_UVS, Quadrant.R0, materialInfo, Direction.NORTH, modelState, null));
87	      bakeSideFaces(builder, interner, modelState, materialInfo);
88	   }
89	
90	   private static void bakeSideFaces(
91	      final QuadCollection.Builder builder, final ModelBaker.Interner interner, final ModelState modelState, final BakedQuad.MaterialInfo materialInfo
92	   ) {
93	      SpriteContents sprite = materialInfo.sprite().contents();
94	      float xScale = 16.0F / sprite.width();
95	      float yScale = 16.0F / sprite.height();
96	      Vector3f from = new Vector3f();
97	      Vector3f to = new Vector3f();
98	
99	      for (ItemModelGenerator.SideFace sideFace : getSideFaces(sprite)) {
100	         float x = sideFace.x();
101	         float y = sideFace.y();
102	         ItemModelGenerator.SideDirection sideDirection = sideFace.facing();
103	         float u0 = x + 0.1F;
104	         float u1 = x + 1.0F - 0.1F;
105	         float v0;
106	         float v1;
107	         if (sideDirection.isHorizontal()) {
108	            v0 = y + 0.1F;
109	            v1 = y + 1.0F - 0.1F;
110	         } else {
111	            v0 = y + 1.0F - 0.1F;
112	            v1 = y + 0.1F;
113	         }
114	
115	         float startX = x;
116	         float startY = y;
117	         float endX = x;
118	         float endY = y;
119	         switch (sideDirection) {
120	            case UP:
121	               endX = x + 1.0F;
122	               break;
123	            case DOWN:
124	               endX = x + 1.0F;
125	               startY = y + 1.0F;
126	               endY = y + 1.0F;
127	               break;
128	            case LEFT:
129	               endY = y + 1.0F;
130	               break;
131	            case RIGHT:
132	               startX = x + 1.0F;
133	               endX = x + 1.0F;
134	               endY = y + 1.0F;
135	         }
136	
137	         startX *= xScale;
138	         endX *= xScale;
139	         startY *= yScale;
140	         endY *= yScale;
141	         startY = 16.0F - startY;
142	         endY = 16.0F - endY;
143	         switch (sideDirection) {
144	            case UP:
145	               from.set(startX, startY, 7.5F);
146	               to.set(endX, startY, 8.5F);
147	               break;
148	            case DOWN:
149	               from.set(startX, endY, 7.5F);
150	               to.set(endX, endY, 8.5F);
151	               break;
152	            case LEFT:
153	               from.set(startX, startY, 7.5F);
154	               to.set(startX, endY, 8.5F);
155	               break;
156	            case RIGHT:
157	               from.set(endX, startY, 7.5F);
158	               to.set(endX, endY, 8.5F);
159	               break;
160	            default:
161	               throw new UnsupportedOperationException();
162	         }
163	
164	         CuboidFace.UVs uvs = new CuboidFace.UVs(u0 * xScale, v0 * yScale, u1 * xScale, v1 * yScale);
165	         builder.addUnculledFace(FaceBakery.bakeQuad(interner, from, to, uvs, Quadrant.R0, materialInfo, sideDirection.getDirection(), modelState, null));
166	      }
167	   }
168	
169	   private static Collection<ItemModelGenerator.SideFace> getSideFaces(final SpriteContents sprite) {
170	      int width = sprite.width();
171	      int height = sprite.height();
172	      Set<ItemModelGenerator.SideFace> sideFaces = new HashSet<>();
173	      sprite.getUniqueFrames().forEach(frame -> {
174	         for (int y = 0; y < height; y++) {
175	            for (int x = 0; x < width; x++) {
176	               boolean thisOpaque = !isTransparent(sprite, frame, x, y, width, height);
177	               if (thisOpaque) {
178	                  checkTransition(ItemModelGenerator.SideDirection.UP, sideFaces, sprite, frame, x, y, width, height);
179	                  checkTransition(ItemModelGenerator.SideDirection.DOWN, sideFaces, sprite, frame, x, y, width, height);
180	                  checkTransition(ItemModelGenerator.SideDirection.LEFT, sideFaces, sprite, frame, x, y, width, height);
181	                  checkTransition(ItemModelGenerator.SideDirection.RIGHT, sideFaces, sprite, frame, x, y, width, height);
182	               }
183	            }
184	         }
185	      });
186	      return sideFaces;
187	   }
188	
189	   private static void checkTransition(
190	      final ItemModelGenerator.SideDirection facing,
191	      final Set<ItemModelGenerator.SideFace> sideFaces,
192	      final SpriteContents sprite,
193	      final int frame,
194	      final int x,
195	      final int y,
196	      final int width,
197	      final int height
198	   ) {
199	      if (isTransparent(sprite, frame, x - facing.direction.getStepX(), y - facing.direction.getStepY(), width, height)) {
200	         sideFaces.add(new ItemModelGenerator.SideFace(facing, x, y));
201	      }
202	   }
203	
204	   private static boolean isTransparent(final SpriteContents sprite, final int frame, final int x, final int y, final int width, final int height) {
205	      return x >= 0 && y >= 0 && x < width && y < height ? sprite.isTransparent(frame, x, y) : true;
206	   }
207	
208	   private record ItemLayerKey(Material.Baked material, ModelState modelState, int layerIndex) implements ModelBaker.SharedOperationKey<QuadCollection> {
209	      public QuadCollection compute(final ModelBaker modelBakery) {
210	         QuadCollection.Builder builder = new QuadCollection.Builder();
211	         BakedQuad.MaterialInfo materialInfo = modelBakery.interner()
212	            .materialInfo(BakedQuad.MaterialInfo.of(this.material, this.material.sprite().transparency(), this.layerIndex, true, 0));
213	         ItemModelGenerator.bakeExtrudedSprite(builder, modelBakery.interner(), this.modelState, materialInfo);
214	         return builder.build();
215	      }
216	   }
217	
218	   private static enum SideDirection {
219	      UP(Direction.UP),
220	      DOWN(Direction.DOWN),
221	      LEFT(Direction.EAST),
222	      RIGHT(Direction.WEST);
223	
224	      private final Direction direction;
225	
226	      private SideDirection(final Direction direction) {
227	         this.direction = direction;
228	      }
229	
230	      public Direction getDirection() {
231	         return this.direction;
232	      }
233	
234	      private boolean isHorizontal() {
235	         return this == DOWN || this == UP;
236	      }
