    17	   private static final Splitter EQUAL_SPLITTER = Splitter.on('=').limit(2);
    18	
    19	   public static <O, S extends StateHolder<O, S>> Predicate<StateHolder<O, S>> predicate(final StateDefinition<O, S> stateDefinition, final String properties) {
    20	      Map<Property<?>, Comparable<?>> map = new HashMap<>();
    21	
    22	      for (String keyValue : COMMA_SPLITTER.split(properties)) {
    23	         Iterator<String> iterator = EQUAL_SPLITTER.split(keyValue).iterator();
    24	         if (iterator.hasNext()) {
    25	            String propertyName = iterator.next();
    26	            Property<?> property = stateDefinition.getProperty(propertyName);
    27	            if (property != null && iterator.hasNext()) {
    28	               String propertyValue = iterator.next();
    29	               Comparable<?> value = getValueHelper((Property<Comparable<?>>)property, propertyValue);
    30	               if (value == null) {
    31	                  throw new RuntimeException(
    32	                     "Unknown value: '" + propertyValue + "' for blockstate property: '" + propertyName + "' " + property.getPossibleValues()
