    43	      return input -> {
    44	         for (Entry<Property<?>, Comparable<?>> entry : map.entrySet()) {
    45	            if (!Objects.equals(input.getValue(entry.getKey()), entry.getValue())) {
    46	               return false;
    47	            }
    48	         }
    49	
    50	         return true;
    51	      };
