    15	   public static final BlockModelRotation IDENTITY = get(OctahedralGroup.IDENTITY);
    16	   private final OctahedralGroup orientation;
    17	   private final Transformation transformation;
    18	   private final Map<Direction, Matrix4fc> faceMapping = new EnumMap<>(Direction.class);
    19	   private final Map<Direction, Matrix4fc> inverseFaceMapping = new EnumMap<>(Direction.class);
    20	   private final BlockModelRotation.WithUvLock withUvLock = new BlockModelRotation.WithUvLock(this);
    21	
    22	   private BlockModelRotation(final OctahedralGroup orientation) {
    23	      this.orientation = orientation;
    24	      if (orientation != OctahedralGroup.IDENTITY) {
    25	         this.transformation = new Transformation(new Matrix4f(orientation.transformation()));
    26	      } else {
    27	         this.transformation = Transformation.IDENTITY;
    28	      }
    29	
    30	      for (Direction face : Direction.values()) {
    31	         Matrix4fc faceTransform = BlockMath.getFaceTransformation(this.transformation, face).getMatrix();
    32	         this.faceMapping.put(face, faceTransform);
