    22	public class ModelBlockRenderer {
    23	   private static final Direction[] DIRECTIONS = Direction.values();
    24	   private final BlockModelLighter lighter;
    25	   private final boolean ambientOcclusion;
    26	   private final boolean cull;
    27	   private final BlockColors blockColors;
    28	   private final RandomSource random = RandomSource.createThreadLocalInstance(0L);
    29	   private final List<BlockStateModelPart> parts = new ObjectArrayList();
    30	   private final BlockPos.MutableBlockPos scratchPos = new BlockPos.MutableBlockPos();
    31	   private final QuadInstance quadInstance = new QuadInstance();
    32	   private int tintCacheIndex = -1;
    33	   private int tintCacheValue;
    34	   private boolean tintSourcesInitialized;
    35	   private final List<@Nullable BlockTintSource> tintSources = new ObjectArrayList();
    36	   private final IntList computedTintValues = new IntArrayList();
    37	
    38	   public ModelBlockRenderer(final boolean ambientOcclusion, final boolean cull, final BlockColors blockColors) {
    39	      this.lighter = new BlockModelLighter();
    40	      this.ambientOcclusion = ambientOcclusion;
    41	      this.cull = cull;
    42	      this.blockColors = blockColors;
    43	   }
    44	
    45	   public static boolean forceOpaque(final boolean cutoutLeaves, final BlockState blockState) {
    46	      return !cutoutLeaves && blockState.getBlock() instanceof LeavesBlock;
    47	   }
    48	
    49	   public void tesselateBlock(
    50	      final BlockQuadOutput output,
    51	      final float x,
    52	      final float y,
    53	      final float z,
    54	      final BlockAndTintGetter level,
    55	      final BlockPos pos,
    56	      final BlockState blockState,
    57	      final BlockStateModel model,
    58	      final long seed
    59	   ) {
    60	      this.random.setSeed(seed);
    61	      model.collectParts(this.random, this.parts);
    62	      if (!this.parts.isEmpty()) {
    63	         try {
    64	            Vec3 offset = blockState.getOffset(pos);
    65	            if (this.ambientOcclusion && blockState.getLightEmission() == 0 && this.parts.getFirst().useAmbientOcclusion()) {
    66	               this.tesselateAmbientOcclusion(output, x + (float)offset.x, y + (float)offset.y, z + (float)offset.z, this.parts, level, blockState, pos);
    67	            } else {
    68	               this.tesselateFlat(output, x + (float)offset.x, y + (float)offset.y, z + (float)offset.z, this.parts, level, blockState, pos);
    69	            }
    70	         } finally {
    71	            this.parts.clear();
    72	            this.resetTintCache();
    73	         }
    74	      }
    75	   }
