    77	   private void configureTintCache(final BlockState blockState) {
    78	      List<BlockTintSource> tintSources = this.blockColors.getTintSources(blockState);
    79	      int tintSourceCount = tintSources.size();
    80	      if (tintSourceCount > 0) {
    81	         this.tintSources.addAll(tintSources);
    82	
    83	         for (int i = 0; i < tintSourceCount; i++) {
    84	            this.computedTintValues.add(-1);
    85	         }
    86	      }
    87	   }
    88	
    89	   private void resetTintCache() {
    90	      this.tintCacheIndex = -1;
    91	      if (this.tintSourcesInitialized) {
    92	         this.tintSources.clear();
    93	         this.computedTintValues.clear();
    94	         this.tintSourcesInitialized = false;
    95	      }
    96	   }
    97	
    98	   private void tesselateAmbientOcclusion(
    99	      final BlockQuadOutput output,
   100	      final float x,
   101	      final float y,
   102	      final float z,
   103	      final List<BlockStateModelPart> parts,
   104	      final BlockAndTintGetter level,
   105	      final BlockState state,
   106	      final BlockPos pos
   107	   ) {
