   137	         for (BakedQuad quad : part.getQuads(null)) {
   138	            this.lighter.prepareQuadAmbientOcclusion(level, state, pos, quad, this.quadInstance);
   139	            this.putQuadWithTint(output, x, y, z, level, state, pos, quad);
   140	         }
   141	      }
   142	   }
