import json,glob,collections,os
cache={}
def load(n):
    n=n.replace('minecraft:','')
    if n in cache: return cache[n]
    p=n+'.json'
    try: d=json.load(open(p,encoding='utf-8'))
    except Exception: d=None
    cache[n]=d; return d
unres=[]
missing_models=[]
for f in sorted(glob.glob('**/*.json',recursive=True)):
    n=os.path.splitext(f)[0].replace(os.sep,'/')
    merged={}
    cur=n; seen=set()
    while cur and cur not in seen:
        seen.add(cur); m=load(cur)
        if m is None:
            missing_models.append((n,cur)); break
        for k,v in (m.get('textures') or {}).items(): merged[k]=v
        cur=m.get('parent')
    def isref(v): return isinstance(v,str) and v.startswith('#')
    for k,v in merged.items():
        if not isref(v): continue
        seen2=set(); c=v
        while isref(c):
            key=c[1:]
            if key in seen2: break
            seen2.add(key)
            c=merged.get(key, None)
            if c is None: break
        if c is None or isref(c): unres.append((n,k,v))
print('unresolved texture variables:',len(unres))
for x in unres[:30]: print('  ',x)
print('broken parent refs:',len(missing_models))
